// === FORMAT NOTIFIKASI SORE BSJP (Beli Sore Jual Pagi) ===
// ⚠️ GANTI nomor ini dengan nomor WA tujuan kamu (format 62xxxxxxxxxx)
const NOMOR_TUJUAN = 'GANTI-DENGAN-NOMOR-WA';

const BATAS_KARAKTER_WA = 3500;
function splitPesan(pesan, batas = BATAS_KARAKTER_WA) {
  if (pesan.length <= batas) return [pesan];
  const hasil = [];
  let sisa = pesan;
  while (sisa.length > batas) {
    let potong = sisa.lastIndexOf('\n', batas);
    if (potong <= 0) potong = batas;
    hasil.push(sisa.slice(0, potong));
    sisa = sisa.slice(potong);
  }
  if (sisa.length > 0) hasil.push(sisa);
  return hasil;
}

function rp(angka) {
  if (angka === undefined || angka === null || angka === '') return 'N/A';
  return `Rp${Number(angka).toLocaleString('id-ID')}`;
}

function fmtMiliar(angka) {
  if (angka === undefined || angka === null || angka === '') return '-';
  return `Rp${(Number(angka) / 1e9).toFixed(1)} M`;
}

const rawInput = $input.first().json;
const inputHttp = rawInput || {};
const gagal = Boolean(inputHttp.error) || inputHttp.status !== 'success';

if (gagal) {
  const e = inputHttp.error || {};
  const detailError = inputHttp.detail || e.message || e.description || 'Server tidak merespons.';
  const pesan = `⚠️ *Notifikasi sore BSJP gagal.*\n${detailError}\n\nPeriksa endpoint /v1/screener/bsjp.`;
  return [{ json: { pesan_wa: pesan, to: NOMOR_TUJUAN } }];
}

const data = inputHttp.data || inputHttp;
const list = data.radar_bsjp_aktif || [];
const tanggal = new Date().toLocaleDateString('id-ID', { weekday: 'long', day: 'numeric', month: 'long' });

let t = `🛒 *NOTIFIKASI SORE — BSJP* (${tanggal})\n`;
t += `━━━━━━━━━━━━━━━━━━━━\n`;
t += `_Beli di close hari ini, jual di open besok pagi._\n\n`;

if (list.length === 0) {
  t += `😴 *TIDAK ADA saham yang lolos filter BSJP hari ini.*\n`;
  t += `_Strategi hanya aktif saat momentum kuat (kenaikan signifikan + volume meledak + close kuat)._`;
} else {
  list.forEach((s, i) => {
    const d = s.detail_sinyal || {};
    const r = s.rekomendasi_bsjp || {};
    const g = s.statistik_gap_historis || {};
    const pct = (d.kenaikan_hari_ini_persen !== undefined && d.kenaikan_hari_ini_persen !== 'N/A')
      ? `+${d.kenaikan_hari_ini_persen}%` : '';
    t += `${i + 1}. *${s.saham}* — ${rp(s.harga_saat_ini)} ${pct}\n`;
    t += `   📈 Naik: ${d.kenaikan_hari_ini_persen}% | Close pos: ${d.posisi_close_di_range} | Vol: ${d.rasio_volume_vs_rata20}x\n`;
    t += `   💰 Nilai: ${fmtMiliar(d.nilai_transaksi_rupiah)} | RSI: ${d.rsi_14} | ADX: ${d.adx_14}\n`;
    if (r.aktif) {
      t += `   🎯 Beli ~${rp(r.harga_beli_acuan)} | Target: ${rp(r.target_jual_estimasi)} | CL: ${rp(r.harga_cut_loss_pagi)}\n`;
      if (g.probabilitas_gap_up_persen !== undefined && g.probabilitas_gap_up_persen !== null) {
        t += `   📊 Prob gap up historis: ${g.probabilitas_gap_up_persen}%\n`;
      }
    }
    t += `\n`;
  });
}

if (data.peringatan) t += `\n⚠️ ${data.peringatan}\n`;
t += `\n📌 _Exit besok pagi MANUAL (09.00-09.30 WIB). Patuhi cut loss jika gap down — jangan ubah jadi swing._`;

return splitPesan(t).map((p) => ({ json: { pesan_wa: p, to: NOMOR_TUJUAN } }));
